package riskclient

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/status"

	"github.com/arcbjorn/credence/gateway/riskpb"
)

// GRPCClient calls the risk service over gRPC.
//
// `docs/10` gates an isolated transport change on passing the same
// reference vectors and acceptance matrix **without changing contracts,
// schemas, model or fixtures**. This is that transport: the stubs are
// generated by `protoc-gen-go-grpc` from `schemas/proto/risk.proto`, the
// same file tonic generates the Rust server from, so the two ends cannot
// drift.
//
// **It carries JSON payloads as `bytes`.** The engine hashes the
// snapshot and the policy exactly as the gateway retained them, so a
// protobuf schema that decomposed them into fields would re-serialize on
// the way out and change what is hashed -- a retained assessment would
// stop reproducing. The canonical encoding stays JSON and stays frozen;
// gRPC carries it.
//
// It satisfies the same interface as the HTTP `Client`, so a caller
// chooses a transport at construction and nothing downstream knows which
// one it got. That is what makes "the matrix passes on both" checkable.
type GRPCClient struct {
	conn    *grpc.ClientConn
	client  riskpb.RiskClient
	timeout time.Duration
}

// NewGRPC dials the service. The connection is lazy: gRPC does not
// actually connect until the first call, so a service that starts after
// the gateway is not an error here.
func NewGRPC(target string, timeout time.Duration) (*GRPCClient, error) {
	conn, err := grpc.NewClient(target,
		// Plaintext, deliberately. This hop is localhost between two
		// processes the operator runs; TLS here would protect nothing
		// and `docs/01` does not claim otherwise. A deployment that
		// moved this boundary across a network must add credentials,
		// and that is a deployment decision rather than a code one.
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		// Mirror the HTTP client's ceiling so neither transport accepts
		// what the other refuses.
		grpc.WithDefaultCallOptions(
			grpc.MaxCallRecvMsgSize(MaxBodyBytes),
			grpc.MaxCallSendMsgSize(MaxBodyBytes),
		),
	)
	if err != nil {
		return nil, fmt.Errorf("dial risk service: %w", err)
	}
	return &GRPCClient{
		conn:    conn,
		client:  riskpb.NewRiskClient(conn),
		timeout: timeout,
	}, nil
}

func (c *GRPCClient) Close() error {
	return c.conn.Close()
}

// Assess evaluates a snapshot. `input` and `policy` pass through
// untouched, for the same reason the HTTP client does not reshape them.
func (c *GRPCClient) Assess(
	ctx context.Context,
	input, policy json.RawMessage,
) (json.RawMessage, error) {
	if err := c.checkSize(input, "input"); err != nil {
		return nil, err
	}
	if err := c.checkSize(policy, "policy"); err != nil {
		return nil, err
	}

	ctx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()

	res, err := c.client.Assess(ctx, &riskpb.AssessRequest{
		Input:  input,
		Policy: policy,
	})
	if err != nil {
		return nil, asServiceError("assess", err)
	}
	return res.GetAssessment(), nil
}

// Replay re-evaluates a retained assessment against its retained input.
func (c *GRPCClient) Replay(
	ctx context.Context,
	assessment, input, policy json.RawMessage,
) (*ReplayResult, error) {
	for name, payload := range map[string]json.RawMessage{
		"assessment": assessment, "input": input, "policy": policy,
	} {
		if err := c.checkSize(payload, name); err != nil {
			return nil, err
		}
	}

	ctx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()

	res, err := c.client.Replay(ctx, &riskpb.ReplayRequest{
		Assessment: assessment,
		Input:      input,
		Policy:     policy,
	})
	if err != nil {
		return nil, asServiceError("replay", err)
	}

	return &ReplayResult{
		Matched:      res.GetMatched(),
		AssessmentID: res.GetAssessmentId(),
		InputHash:    res.GetInputHash(),
		Differences:  res.GetDifferences(),
	}, nil
}

// Health reports whether the service answers, and with WHICH engine.
//
// The model hash is checked rather than discarded: a healthy service
// running a different engine is worse than one that is down, because the
// caller would receive assessments it cannot reproduce.
func (c *GRPCClient) Health(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()

	res, err := c.client.Health(ctx, &riskpb.HealthRequest{})
	if err != nil {
		return asServiceError("health", err)
	}
	if res.GetModelHash() == "" {
		return fmt.Errorf("risk service reported no model hash")
	}
	return nil
}

// ModelHash returns the engine the service is running.
func (c *GRPCClient) ModelHash(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()

	res, err := c.client.Health(ctx, &riskpb.HealthRequest{})
	if err != nil {
		return "", asServiceError("health", err)
	}
	return res.GetModelHash(), nil
}

// checkSize refuses locally rather than sending a request the service
// will reject, matching the HTTP client.
func (c *GRPCClient) checkSize(payload json.RawMessage, name string) error {
	if len(payload) > MaxBodyBytes {
		return fmt.Errorf("%s is %d bytes, over the limit %d", name, len(payload), MaxBodyBytes)
	}
	return nil
}

// asServiceError maps a gRPC status onto the same error type the HTTP
// client returns, so a caller handles one shape regardless of transport.
//
// The mapping is the inverse of the server's: the distinction between
// "the caller sent something invalid" and "the service failed" has to
// survive the wire, or a caller cannot tell a bug from a retry.
func asServiceError(call string, err error) error {
	st, ok := status.FromError(err)
	if !ok {
		return fmt.Errorf("call %s: %w", call, err)
	}
	switch st.Code() {
	case codes.InvalidArgument:
		return &ServiceError{Status: 400, Code: "invalid_argument", Detail: st.Message()}
	case codes.ResourceExhausted:
		return &ServiceError{Status: 413, Code: "too_large", Detail: st.Message()}
	case codes.NotFound:
		return &ServiceError{Status: 404, Code: "not_found", Detail: st.Message()}
	case codes.Unavailable, codes.DeadlineExceeded:
		// NOT a ServiceError: the service never formed a verdict, so the
		// caller must treat this as "unknown" rather than "refused".
		return fmt.Errorf("call %s: %w", call, err)
	default:
		return &ServiceError{Status: 500, Code: st.Code().String(), Detail: st.Message()}
	}
}
